const C=["Markets and welfare","Consumers and producers","Market structure","Labour and distribution","Macroeconomics","Growth","International","Statistics and econometrics","Finance and risk"],c=(e,t,n,o=80)=>Array.from({length:o+1},(l,a)=>{const r=t+(n-t)*a/o;return{x:r,y:e(r)}}),m=(e,t,n)=>e.filter(o=>Number.isFinite(o.y)&&o.y>=t-1e-9&&o.y<=n+1e-9),i=(e,t=2)=>String(Number(e.toFixed(t))),d=(e,t,n,o,l,a)=>({id:e,label:t,min:n,max:o,step:l,value:a}),k=[{id:"supply-demand",area:"Markets and welfare",title:"Supply and demand",level:"beginner",topic:"welfare-measures",params:[d("A","Demand intercept (shifts demand)",60,140,5,100),d("B","Demand slope",.5,3,.1,1),d("C","Supply intercept (shifts supply)",0,50,5,20),d("D","Supply slope",.5,3,.1,1)],build:({A:e,B:t,C:n,D:o})=>{const l=Math.max(0,(e-n)/(t+o)),a=e-t*l,r=.5*(e-a)*l,s=.5*(a-n)*l,h=Math.max(10,e/t)*1.05;return{xLabel:"Quantity Q",yLabel:"Price P",xDomain:[0,h],yDomain:[0,150],series:[{kind:"polygon",name:"Consumer surplus",pts:[{x:0,y:e},{x:0,y:a},{x:l,y:a}],color:1,opacity:.18},{kind:"polygon",name:"Producer surplus",pts:[{x:0,y:a},{x:0,y:n},{x:l,y:a}],color:3,opacity:.18},{kind:"line",name:"Demand P = A - BQ",pts:m(c(u=>e-t*u,0,h),0,150),color:1},{kind:"line",name:"Supply P = C + DQ",pts:m(c(u=>n+o*u,0,h),0,150),color:2}],annots:[{kind:"dot",x:l,y:a,label:"E"},{kind:"segment",x1:l,y1:0,x2:l,y2:a,dash:!0},{kind:"segment",x1:0,y1:a,x2:l,y2:a,dash:!0}],readouts:[{label:"Equilibrium price",value:i(a)},{label:"Equilibrium quantity",value:i(l)},{label:"Consumer surplus",value:i(r)},{label:"Producer surplus",value:i(s)},{label:"Total surplus",value:i(r+s)}]}},brief:"Demand shows how much buyers want at each price; supply shows how much sellers offer. Where they cross, the market clears: the equilibrium price and quantity.",read:["Price is on the vertical axis and quantity on the horizontal, by convention since Marshall.","A change in price moves along a curve; a change in anything else (income, costs, tastes) shifts the curve.","The blue triangle is consumer surplus: buyers' willingness to pay above the price. The green triangle is producer surplus.","Total surplus is largest at the competitive equilibrium when there are no externalities."],example:"With demand $P = 100 - Q$ and supply $P = 20 + Q$: setting them equal gives $Q^* = 40$, $P^* = 60$. Consumer surplus $= \\tfrac12(100-60)(40) = 800$; producer surplus $= \\tfrac12(60-20)(40) = 800$.",scenario:"**Case: tomatoes in Kalimati market before Dashain.** Festival demand rises: raise the demand intercept. Price and quantity both rise. If a landslide blocks supply routes from the hills, the supply curve shifts up (raise the supply intercept): price rises but quantity falls. Watching both moves at once tells you which shock dominated.",mistakes:["Saying demand fell when price rose: a price rise moves along demand, it does not shift it.","Forgetting that both curves can shift at once; then the direction of one variable is ambiguous.","Drawing price on the horizontal axis."],tryThis:["Raise the demand intercept: what happens to P and Q?","Make demand flatter (lower slope B): does a supply shift now change price more or less?"]},{id:"price-ceiling",area:"Markets and welfare",title:"Price ceiling and shortage",level:"beginner",topic:"welfare-measures",params:[d("Pc","Ceiling price",20,70,1,45)],build:({Pc:e})=>{const s=e<60,h=s?(e-20)/1:40,u=s?(100-e)/1:40,p=100-1*h,f=s?.5*(p-e)*(40-h):0;return{xLabel:"Quantity Q",yLabel:"Price P",xDomain:[0,100],yDomain:[0,110],series:[...s?[{kind:"polygon",name:"Deadweight loss",pts:[{x:h,y:p},{x:h,y:e},{x:40,y:60}],color:5,opacity:.25}]:[],{kind:"line",name:"Demand",pts:c(v=>100-1*v,0,100),color:1},{kind:"line",name:"Supply",pts:m(c(v=>20+1*v,0,100),0,110),color:2},{kind:"line",name:"Ceiling",pts:[{x:0,y:e},{x:100,y:e}],color:4,dash:!0}],annots:s?[{kind:"dot",x:h,y:e,label:"Qs"},{kind:"dot",x:u,y:e,label:"Qd"},{kind:"dot",x:40,y:60,label:"E"}]:[{kind:"dot",x:40,y:60,label:"E"}],readouts:[{label:"Equilibrium price",value:i(60)},{label:"Ceiling binds?",value:s?"Yes":"No (above equilibrium)"},{label:"Quantity supplied",value:i(h)},{label:"Quantity demanded",value:i(u)},{label:"Shortage",value:i(Math.max(0,u-h))},{label:"Deadweight loss",value:i(f)}]}},brief:"A legal maximum price. If it is below the equilibrium price it binds: buyers want more than sellers supply, so there is a shortage and some trades worth making do not happen.",read:["A ceiling above equilibrium does nothing.","When it binds, quantity traded is set by the short side of the market: supply.","The red triangle is the deadweight loss: lost trades where buyers valued the good above its cost.","Shortages bring queues, black markets and quality cuts, which the simple graph does not show."],example:"Equilibrium $P^* = 60$, $Q^* = 40$. A ceiling of 45 gives $Q_s = 25$, $Q_d = 55$: a shortage of 30. Buyers would pay $100 - 25 = 75$ for the 25th unit, so $DWL = \\tfrac12(75 - 45)(40 - 25) = 225$.",scenario:"**Case: fuel price controls.** Suppose the government holds the retail price of cooking gas below the import cost. Queues form at dealers, cylinders move to black markets, and the state oil company makes losses that must be covered. Try lowering the ceiling and watch the shortage and deadweight loss grow.",mistakes:["Calling any ceiling harmful: a ceiling above equilibrium has no effect.","Measuring the deadweight loss with the ceiling price instead of the buyers' willingness to pay at the reduced quantity."],tryThis:["Set the ceiling above 60: what changes?","Lower it step by step: how fast does the deadweight loss grow?"]},{id:"tax-incidence",area:"Markets and welfare",title:"Tax incidence and deadweight loss",level:"intermediate",topic:"welfare-measures",params:[d("t","Tax per unit",0,40,1,20),d("B","Demand slope (steeper = less elastic)",.3,3,.1,1),d("D","Supply slope (steeper = less elastic)",.3,3,.1,1)],build:({t:e,B:t,D:n})=>{const a=90/(t+n),r=100-t*a,s=Math.max(0,(90-e)/(t+n)),h=100-t*s,u=h-e,p=e*s,f=.5*e*(a-s),v=e?(h-r)/e:0,b=Math.max(a*1.4,10);return{xLabel:"Quantity Q",yLabel:"Price P",xDomain:[0,b],yDomain:[0,110],series:[{kind:"polygon",name:"Tax revenue",pts:[{x:0,y:h},{x:s,y:h},{x:s,y:u},{x:0,y:u}],color:4,opacity:.18},{kind:"polygon",name:"Deadweight loss",pts:[{x:s,y:h},{x:s,y:u},{x:a,y:r}],color:5,opacity:.3},{kind:"line",name:"Demand",pts:m(c(w=>100-t*w,0,b),0,110),color:1},{kind:"line",name:"Supply",pts:m(c(w=>10+n*w,0,b),0,110),color:2},{kind:"line",name:"Supply plus tax",pts:m(c(w=>10+e+n*w,0,b),0,110),color:2,dash:!0}],annots:[{kind:"dot",x:a,y:r,label:"E0"},{kind:"dot",x:s,y:h,label:"Pb"},{kind:"dot",x:s,y:u,label:"Ps"}],readouts:[{label:"Price buyers pay",value:i(h)},{label:"Price sellers keep",value:i(u)},{label:"Buyers' share of tax",value:i(v*100,0)+"%"},{label:"Tax revenue",value:i(p)},{label:"Deadweight loss",value:i(f)}]}},brief:"Who really pays a tax depends on elasticities, not on who hands the money to the government. The less elastic side bears more of it. The tax also destroys some trades: the deadweight loss.",read:["The dashed line is supply shifted up by the tax.","The gap between what buyers pay and sellers keep equals the tax.","The purple rectangle is revenue; the red triangle is the deadweight loss.","Buyers' share of the tax equals $\\frac{\\text{supply slope}}{\\text{demand slope} + \\text{supply slope}}$ with linear curves drawn this way."],example:"Demand $P = 100 - Q$, supply $P = 10 + Q$, tax 20. Without the tax $Q = 45$, $P = 55$. With it, $Q = 35$, buyers pay 65, sellers keep 45: each side bears 10. Revenue $= 20 \\times 35 = 700$; $DWL = \\tfrac12 \\times 20 \\times 10 = 100$.",scenario:"**Case: excise duty on cigarettes.** Smokers' demand is inelastic (make demand steep). Most of the duty falls on smokers, revenue is large and the deadweight loss small, which is why such taxes are popular with ministries. A health benefit (lower smoking) is outside this graph.",mistakes:["Assuming the side that legally pays bears the tax.","Forgetting that deadweight loss grows with the square of the tax."],tryThis:["Double the tax: does the deadweight loss double or quadruple?","Make demand very steep: who pays now?"]},{id:"externality",area:"Markets and welfare",title:"Negative externality and Pigouvian tax",level:"intermediate",topic:"welfare-measures",params:[d("E","External cost per unit",0,40,1,20),d("tax","Pigouvian tax",0,40,1,0)],build:({E:e,tax:t})=>{const r=(90-t)/2,s=(90-e)/2,h=100-1*s,u=100-1*r,p=.5*Math.abs(r-s)*Math.abs(e-t);return{xLabel:"Quantity Q",yLabel:"Price, cost",xDomain:[0,70],yDomain:[0,110],series:[{kind:"polygon",name:"Welfare loss",pts:[{x:s,y:h},{x:r,y:10+1*r+e},{x:r,y:u}],color:5,opacity:.28},{kind:"line",name:"Demand (private benefit)",pts:c(f=>100-1*f,0,70),color:1},{kind:"line",name:"Private cost (supply)",pts:m(c(f=>10+1*f,0,70),0,110),color:2},{kind:"line",name:"Social cost",pts:m(c(f=>10+e+1*f,0,70),0,110),color:5}],annots:[{kind:"dot",x:r,y:u,label:"Market"},{kind:"dot",x:s,y:h,label:"Social optimum"}],readouts:[{label:"Market quantity",value:i(r)},{label:"Efficient quantity",value:i(s)},{label:"Remaining welfare loss",value:i(p)},{label:"Tax that fixes it",value:i(e)}]}},brief:"When production harms others (pollution), the market ignores that cost and produces too much. A tax equal to the external cost per unit (a Pigouvian tax) makes producers face the full social cost.",read:["Social cost lies above private cost by the external cost per unit.","The market settles where demand meets private cost; society would prefer where demand meets social cost.","The red triangle is the welfare loss from overproduction.","Set the tax equal to the external cost and the loss disappears."],example:"External cost 20 per unit: the market produces 45, the efficient level is 35. The loss is $\\tfrac12 \\times 10 \\times 20 = 100$. A tax of 20 moves the market to 35.",scenario:"**Case: brick kilns around the Kathmandu Valley.** Kilns pollute the air that residents breathe. Without a charge they produce too many bricks with old technology. A pollution charge, or a requirement for cleaner kilns, makes the price of bricks reflect the health cost.",mistakes:["Thinking the best quantity of pollution is zero: it is where marginal benefit equals full marginal cost.","Setting the tax equal to the total damage instead of the marginal damage."],tryThis:["Move the tax slider to 20: what happens to the loss?","Set a tax above the external cost: is that efficient?"]},{id:"elasticity",area:"Markets and welfare",title:"Elasticity along a linear demand curve and revenue",level:"beginner",topic:"single-calculus",params:[d("Q0","Point on the demand curve (quantity)",5,95,1,30)],build:({Q0:e})=>{const o=100-1*e,l=-1*(o/e);return{xLabel:"Quantity Q",yLabel:"Price P and revenue / 25",xDomain:[0,100],yDomain:[0,110],series:[{kind:"line",name:"Demand P = 100 - Q",pts:c(a=>100-1*a,0,100),color:1},{kind:"line",name:"Total revenue / 25",pts:c(a=>(100-1*a)*a/25,0,100),color:3}],annots:[{kind:"dot",x:e,y:o,label:"Point"},{kind:"vline",x:50,label:"Unit elastic"}],readouts:[{label:"Price",value:i(o)},{label:"Elasticity",value:i(l)},{label:"Region",value:Math.abs(l)>1?"Elastic: cutting price raises revenue":Math.abs(l)<1?"Inelastic: raising price raises revenue":"Unit elastic: revenue at its maximum"},{label:"Total revenue",value:i(o*e)}]}},brief:"Elasticity measures how strongly quantity responds to price, in percentages. On a straight demand line, the slope is constant but elasticity changes: elastic at the top, inelastic at the bottom.",read:["Above the midpoint demand is elastic; below it inelastic; at the midpoint unit elastic.","Revenue (green, scaled) peaks where elasticity equals minus one.","Elasticity depends on where you are on the curve, not just the slope."],example:"At $Q = 30$, $P = 70$: $\\varepsilon = -1 \\times 70/30 = -2.33$, elastic, so a price cut raises revenue. At $Q = 70$, $P = 30$: $\\varepsilon = -0.43$, inelastic.",scenario:"**Case: Nepal Airlines fares.** On a route where travellers have road alternatives, demand is elastic: cutting fares can raise revenue. On a mountain route with no road, demand is inelastic: higher fares raise revenue but face political limits.",mistakes:["Saying a steep curve is always inelastic: elasticity varies along a straight line.","Forgetting the sign: demand elasticity is negative."],tryThis:["Find the quantity where revenue is largest.","Move to the top of the curve: what does elasticity approach?"]},{id:"budget-indifference",area:"Consumers and producers",title:"Budget line, indifference curves and the optimum",level:"intermediate",topic:"consumer-choice",params:[d("m","Income",40,200,5,100),d("px","Price of x",1,10,.5,4),d("al","Taste for x (alpha)",.2,.8,.05,.5)],build:({m:e,px:t,al:n})=>{const l=n*e/t,a=(1-n)*e/2,r=l**n*a**(1-n),s=h=>u=>(h/u**n)**(1/(1-n));return{xLabel:"Good x",yLabel:"Good y",xDomain:[0,60],yDomain:[0,80],series:[{kind:"line",name:"Budget line",pts:m(c(h=>(e-t*h)/2,0,60),0,80),color:1},{kind:"line",name:"Indifference curve at optimum",pts:m(c(s(r),.5,60),0,80),color:3},{kind:"line",name:"A lower indifference curve",pts:m(c(s(r*.7),.5,60),0,80),color:3,dash:!0}],annots:[{kind:"dot",x:l,y:a,label:"Optimum"}],readouts:[{label:"Optimal x",value:i(l)},{label:"Optimal y",value:i(a)},{label:"MRS at optimum",value:i(n/(1-n)*(a/l))},{label:"Price ratio px/py",value:i(t/2)},{label:"Utility",value:i(r)}]}},brief:"The consumer picks the best bundle they can afford: where the highest indifference curve just touches the budget line. There the marginal rate of substitution equals the price ratio.",read:["The budget line's slope is minus the price ratio; its intercepts are income divided by each price.","Indifference curves further out mean higher utility.","At the tangency, the rate at which the consumer is willing to swap goods (MRS) equals the rate at which the market lets them swap (price ratio).","With Cobb-Douglas tastes, spending on x is always the share alpha of income."],example:"Income 100, $p_x = 4$, $p_y = 2$, $\\alpha = 0.5$: $x^* = 0.5 \\times 100/4 = 12.5$ and $y^* = 25$. MRS $= y/x = 2 = p_x/p_y$.",scenario:"**Case: a remittance receiving household.** A remittance raises income: the budget line moves out in parallel and both goods rise in the same proportion with Cobb-Douglas tastes. If the price of rice (x) rises, the budget line pivots inward on the x axis and the household buys less rice.",mistakes:["Choosing a corner or crossing point instead of the tangency.","Drawing indifference curves that cross: they never do for a rational consumer."],tryThis:["Raise income: how do x and y change?","Raise the price of x: how much of the fall in x is due to the price, and how much to lost purchasing power? (See the next graph.)"]},{id:"income-substitution",area:"Consumers and producers",title:"Income and substitution effects (Slutsky and Hicks)",level:"advanced",topic:"duality-slutsky",params:[d("px1","New price of x",2,10,.5,6)],build:({px1:e})=>{const a=16.666666666666668,r=(1-.5)*100/2,s=a**.5*r**(1-.5),h=.5*100/e,u=(1-.5)*100/2,p=s*(.5/(1-.5)*(2/e))**(1-.5),f=s*((1-.5)/.5*(e/2))**.5,v=e*p+2*f,b=y=>g=>(y/g**.5)**(1/(1-.5)),w=h**.5*u**(1-.5);return{xLabel:"Good x",yLabel:"Good y",xDomain:[0,40],yDomain:[0,60],series:[{kind:"line",name:"Original budget",pts:m(c(y=>(100-3*y)/2,0,40),0,60),color:1,dash:!0},{kind:"line",name:"New budget",pts:m(c(y=>(100-e*y)/2,0,40),0,60),color:1},{kind:"line",name:"Compensated budget",pts:m(c(y=>(v-e*y)/2,0,40),0,60),color:4,dash:!0},{kind:"line",name:"Original indifference curve",pts:m(c(b(s),.5,40),0,60),color:3},{kind:"line",name:"New indifference curve",pts:m(c(b(w),.5,40),0,60),color:3,dash:!0}],annots:[{kind:"dot",x:a,y:r,label:"A"},{kind:"dot",x:p,y:f,label:"B"},{kind:"dot",x:h,y:u,label:"C"}],readouts:[{label:"Substitution effect (A to B)",value:i(p-a)},{label:"Income effect (B to C)",value:i(h-p)},{label:"Total effect (A to C)",value:i(h-a)},{label:"Compensating income",value:i(v-100)}]}},brief:"A price rise has two effects: goods become relatively dearer (substitution effect, always away from the dearer good) and the consumer becomes poorer (income effect). The compensated budget line separates them.",read:["A is the original choice, C the new choice.","B is where the consumer would go if given just enough income to stay on the original indifference curve at new prices (Hicks compensation).","A to B is the substitution effect; B to C the income effect.","For a normal good both effects reduce x; a Giffen good needs a huge opposite income effect."],example:"Income 100, $p_y = 2$, $p_x$ rises from 3 to 6 with $\\alpha = 0.5$: $x$ falls from 16.67 to 8.33. About 4.88 of the fall is substitution and 3.45 is the income effect; the consumer needs about 41 more income to be as well off.",scenario:"**Case: a rise in the price of cooking gas.** Households switch partly to electric induction cooking (substitution) and also cut other spending because they are poorer (income). A cash compensation scheme restores utility but households still use less gas: the substitution effect remains.",mistakes:["Mixing up Hicks (constant utility) and Slutsky (constant purchasing power) compensation.","Thinking compensation cancels the whole change in demand."],tryThis:["Move the price back to 3: all effects vanish.","Raise the price further: which effect grows faster?"]},{id:"ppf",area:"Consumers and producers",title:"Production possibility frontier and opportunity cost",level:"beginner",params:[d("share","Position on the frontier (share of resources to x)",.05,.95,.01,.5),d("growth","Growth (shifts frontier out)",1,1.5,.05,1)],build:({share:e,growth:t})=>{const n=50*t,o=80*t,l=e*Math.PI/2,a=n*Math.sin(l),r=o*Math.cos(l),s=o*o/(n*n)*(a/r);return{xLabel:"Good x (for example clothing)",yLabel:"Good y (for example food)",xDomain:[0,80],yDomain:[0,130],series:[{kind:"line",name:"Frontier",pts:c(h=>o*Math.sqrt(Math.max(0,1-(h/n)**2)),0,n,100),color:1},{kind:"line",name:"Original frontier",pts:c(h=>80*Math.sqrt(Math.max(0,1-(h/50)**2)),0,50,100),color:1,dash:!0}],annots:[{kind:"dot",x:a,y:r,label:"Chosen point"}],readouts:[{label:"Output of x",value:i(a)},{label:"Output of y",value:i(r)},{label:"Opportunity cost of one more x (in y)",value:i(s)}]}},brief:"The frontier shows the most an economy can produce of two goods with its resources. Moving along it means giving up one good to get more of the other: the opportunity cost.",read:["Points inside the frontier waste resources; points outside are unattainable now.","The bowed shape means rising opportunity cost: resources are not equally good at both goods.","Growth (more capital, labour or technology) shifts the frontier out."],example:"Near the y axis, a little clothing costs little food; near the x axis, extra clothing costs a lot of food. The readout shows the slope (marginal rate of transformation).",scenario:"**Case: workers in Nepali agriculture and foreign employment.** When many workers leave for jobs abroad, the domestic frontier shifts in; remittances let the country consume beyond it through imports.",mistakes:["Confusing a movement along the frontier with a shift.","Saying a point inside is efficient."],tryThis:["Move along the frontier: where is opportunity cost highest?","Raise growth: what is the new opportunity cost at the same share?"]},{id:"cost-curves",area:"Consumers and producers",title:"Cost curves: MC, AC and AVC",level:"intermediate",topic:"producer-theory",params:[d("F","Fixed cost",0,200,10,80),d("c","Steepness of rising costs",.2,1,.05,.5)],build:({F:e,c:t})=>{const l=u=>20-8*u+3*t*u*u,a=u=>20-4*u+t*u*u,r=u=>a(u)+e/u,s=4/(2*t);let h=s;for(let u=0;u<60;u++){const p=-4+2*t*h-e/(h*h),f=2*t+2*e/h**3;h-=p/f}return{xLabel:"Output Q",yLabel:"Cost per unit",xDomain:[0,14],yDomain:[0,60],series:[{kind:"line",name:"Marginal cost",pts:m(c(l,.2,14),0,60),color:5},{kind:"line",name:"Average variable cost",pts:m(c(a,.2,14),0,60),color:2},{kind:"line",name:"Average total cost",pts:m(c(r,.3,14),0,60),color:1}],annots:[{kind:"dot",x:s,y:a(s),label:"min AVC"},{kind:"dot",x:h,y:r(h),label:"min AC"}],readouts:[{label:"Output at min AVC",value:i(s)},{label:"Min AVC (shutdown price)",value:i(a(s))},{label:"Output at min AC",value:i(h)},{label:"Min AC (break-even price)",value:i(r(h))}]}},brief:"Marginal cost is the cost of one more unit; average cost is cost per unit. Marginal cost crosses both average curves at their lowest points.",read:["When marginal is below average, average falls; when above, average rises.","The gap between AC and AVC is average fixed cost, which shrinks as output grows.","Min AVC is the shutdown price in the short run; min AC is the break-even price in the long run."],example:"With $TC = F + 20Q - 4Q^2 + 0.5Q^3$, $AVC = 20 - 4Q + 0.5Q^2$ is lowest at $Q = 4$, where $AVC = 12$ and $MC = 20 - 32 + 24 = 12$: they meet.",scenario:"**Case: a small noodle factory in Butwal.** Rent and machines are fixed costs; flour and wages are variable. If noodle prices fall below minimum AVC, the factory should pause production even though rent must still be paid.",mistakes:["Drawing MC crossing AC anywhere but its minimum.","Using fixed costs in the short run shutdown decision."],tryThis:["Raise fixed cost: which curves move?","Change steepness: what happens to the efficient scale?"]},{id:"competitive-firm",area:"Market structure",title:"Competitive firm: price equals marginal cost",level:"intermediate",topic:"producer-theory",params:[d("p","Market price",6,45,.5,24),d("F","Fixed cost",0,150,5,60)],build:({p:e,F:t})=>{const a=b=>20-8*b+1.5*b*b,r=b=>20-4*b+.5*b*b,s=b=>r(b)+t/b,h=64-6*(20-e),u=h>=0?(8+Math.sqrt(h))/(6*.5):0,p=e<r(4/(2*.5)),f=p?0:u,v=p?-t:(e-s(f))*f;return{xLabel:"Output Q",yLabel:"Price, cost per unit",xDomain:[0,14],yDomain:[0,60],series:[...f>0?[{kind:"polygon",name:v>=0?"Profit":"Loss",pts:[{x:0,y:e},{x:f,y:e},{x:f,y:s(f)},{x:0,y:s(f)}],color:v>=0?3:5,opacity:.2}]:[],{kind:"line",name:"Marginal cost",pts:m(c(a,.2,14),0,60),color:5},{kind:"line",name:"Average total cost",pts:m(c(s,.3,14),0,60),color:1},{kind:"line",name:"Average variable cost",pts:m(c(r,.2,14),0,60),color:2,dash:!0},{kind:"line",name:"Price = marginal revenue",pts:[{x:0,y:e},{x:14,y:e}],color:4}],annots:f>0?[{kind:"dot",x:f,y:e,label:"P = MC"}]:[],readouts:[{label:"Output",value:p?"0 (shut down)":i(f)},{label:"Average cost there",value:f?i(s(f)):"-"},{label:"Profit",value:i(v)}]}},brief:"A price taking firm produces where price equals marginal cost (on the rising part of MC). It makes profit if price is above average cost, and shuts down in the short run if price is below average variable cost.",read:["Price is a horizontal line: the firm can sell any amount at the market price.","The profit rectangle is (price minus average cost) times output.","Between min AVC and min AC the firm loses money but still produces, because it covers variable costs.","The MC curve above min AVC is the firm's short run supply curve."],example:"At price 24 the firm sets $20 - 8Q + 1.5Q^2 = 24$, so $Q \\approx 5.79$. Average cost there decides profit or loss.",scenario:"**Case: a dairy cooperative member.** If the milk price paid by the dairy falls, a farmer keeps producing while the price covers feed and labour (variable costs) but would exit in the long run if it stays below average total cost.",mistakes:["Producing where price equals average cost instead of marginal cost.","Shutting down whenever there is a loss."],tryThis:["Lower the price below about 12: the firm shuts down.","Find the price where profit is exactly zero."]},{id:"monopoly",area:"Market structure",title:"Monopoly: MR = MC and deadweight loss",level:"intermediate",topic:"producer-theory",params:[d("A","Demand intercept",60,140,5,100),d("c","Marginal cost",0,50,1,20)],build:({A:e,c:t})=>{const o=Math.max(0,(e-t)/2),l=e-1*o,a=Math.max(0,(e-t)/1),r=.5*(l-t)*(a-o),s=l?(l-t)/l:0;return{xLabel:"Quantity Q",yLabel:"Price, cost",xDomain:[0,140],yDomain:[0,145],series:[{kind:"polygon",name:"Monopoly profit",pts:[{x:0,y:l},{x:o,y:l},{x:o,y:t},{x:0,y:t}],color:3,opacity:.18},{kind:"polygon",name:"Deadweight loss",pts:[{x:o,y:l},{x:o,y:t},{x:a,y:t}],color:5,opacity:.28},{kind:"line",name:"Demand",pts:m(c(h=>e-1*h,0,140),0,145),color:1},{kind:"line",name:"Marginal revenue",pts:m(c(h=>e-2*h,0,140),0,145),color:1,dash:!0},{kind:"line",name:"Marginal cost",pts:[{x:0,y:t},{x:140,y:t}],color:2}],annots:[{kind:"dot",x:o,y:l,label:"Monopoly"},{kind:"dot",x:a,y:t,label:"Competition"}],readouts:[{label:"Monopoly quantity",value:i(o)},{label:"Monopoly price",value:i(l)},{label:"Competitive quantity",value:i(a)},{label:"Deadweight loss",value:i(r)},{label:"Lerner index (P - MC)/P",value:i(s)}]}},brief:"A monopolist chooses output where marginal revenue equals marginal cost, then charges the highest price buyers will pay. It produces less than a competitive market and creates a deadweight loss.",read:["MR lies below demand: to sell one more unit the monopolist must cut the price on all units.","With linear demand, MR has twice the slope of demand.","The green rectangle is profit; the red triangle is the deadweight loss.","The Lerner index measures market power; it equals 1/|elasticity| at the optimum."],example:"Demand $P = 100 - Q$, MC $= 20$: $MR = 100 - 2Q = 20$ gives $Q = 40$, $P = 60$. Competition would give $Q = 80$. $DWL = \\tfrac12 (60 - 20)(80 - 40) = 800$.",scenario:"**Case: a single cable provider in a hill town.** It restricts connections and charges a high price. Allowing a second provider or regulating the price could move output toward the competitive level.",mistakes:["Setting price where MR = MC instead of reading price from the demand curve.","Thinking a monopolist charges the highest possible price: it charges the profit maximising one."],tryThis:["Raise marginal cost: how much of the cost rise passes to price?","Compare deadweight loss with consumer surplus under competition."]},{id:"cournot",area:"Market structure",title:"Cournot duopoly: reaction functions",level:"advanced",topic:"game-theory-nash",params:[d("c1","Firm 1 marginal cost",0,40,1,10),d("c2","Firm 2 marginal cost",0,40,1,10)],build:({c1:e,c2:t})=>{const l=(100-2*e+t)/3,a=(100-2*t+e)/3,r=100-1*(l+a);return{xLabel:"Firm 1 output q1",yLabel:"Firm 2 output q2",xDomain:[0,100],yDomain:[0,100],series:[{kind:"line",name:"Firm 1 best response",pts:Array.from({length:81},(s,h)=>{const u=100*h/80;return{x:Math.max(0,(100-e-1*u)/2),y:u}}),color:1},{kind:"line",name:"Firm 2 best response",pts:m(c(s=>Math.max(0,(100-t-1*s)/2),0,100),0,100),color:2}],annots:[{kind:"dot",x:l,y:a,label:"Nash equilibrium"}],readouts:[{label:"q1",value:i(l)},{label:"q2",value:i(a)},{label:"Market price",value:i(r)},{label:"Firm 1 profit",value:i((r-e)*l)},{label:"Firm 2 profit",value:i((r-t)*a)}]}},brief:"Each firm chooses its output given the other's. A best response (reaction) function says the best output for each rival output. The Nash equilibrium is where both are best responding: the curves cross.",read:["Each reaction function slopes down: if the rival produces more, my best response is to produce less (strategic substitutes).","A lower marginal cost shifts a firm's reaction function out and raises its equilibrium share.","Market price lies between the monopoly and competitive prices."],example:"Demand $P = 100 - (q_1 + q_2)$, both costs 10: $q_i = 30$ each, $P = 40$, profit 900 each.",scenario:"**Case: two cement producers supplying a region.** If one adopts cheaper fuel (lower cost), it expands and the rival contracts. Watching the equilibrium move shows how cost advantages translate into market share.",mistakes:["Treating the rival's output as fixed after a shock: both adjust.","Confusing Cournot (quantities) with Bertrand (prices), where identical firms price at marginal cost."],tryThis:["Lower firm 1's cost to 0: what happens to firm 2?","Set both costs to 40: how big is the market?"]},{id:"minimum-wage",area:"Labour and distribution",title:"Minimum wage in a competitive labour market",level:"beginner",params:[d("w","Minimum wage",10,60,1,40)],build:({w:e})=>{const s=e>45,h=s?(80-e)/1:35,u=s?(e-10)/1:35;return{xLabel:"Workers L",yLabel:"Wage W",xDomain:[0,80],yDomain:[0,90],series:[{kind:"line",name:"Labour demand",pts:m(c(p=>80-1*p,0,80),0,90),color:1},{kind:"line",name:"Labour supply",pts:m(c(p=>10+1*p,0,80),0,90),color:2},{kind:"line",name:"Minimum wage",pts:[{x:0,y:e},{x:80,y:e}],color:4,dash:!0}],annots:s?[{kind:"dot",x:h,y:e,label:"Jobs"},{kind:"dot",x:u,y:e,label:"Job seekers"}]:[{kind:"dot",x:35,y:45,label:"E"}],readouts:[{label:"Market wage",value:i(45)},{label:"Employment",value:i(h)},{label:"Unemployment created",value:i(Math.max(0,u-h))}]}},brief:"In a competitive labour market, a minimum wage above the market wage raises pay for those who keep jobs but reduces employment and creates unemployment.",read:["Labour demand is firms' demand for workers (the value of what an extra worker produces).","A binding minimum wage cuts the number of jobs and draws more people into looking for work.","Real labour markets often have employer power, which changes the result: see the monopsony graph."],example:"Market wage 45 with 35 workers. A minimum of 50 gives 30 jobs and 40 job seekers: 10 unemployed.",scenario:"**Case: Nepal's minimum wage revisions.** In formal factories with competition for workers, a large rise could reduce hiring or push work into the informal sector. Empirical work (like Card and Krueger) finds effects are often smaller than this simple model predicts.",mistakes:["Treating this model as the whole story: evidence often shows small job losses.","Ignoring the informal sector, which is large in Nepal."],tryThis:["Set the minimum below the market wage: nothing changes.","Compare with the monopsony graph at the same minimum wage."]},{id:"monopsony",area:"Labour and distribution",title:"Monopsony: when a minimum wage can raise jobs",level:"advanced",params:[d("w","Minimum wage (0 = none)",0,70,1,0)],build:({w:e})=>{const a=26.666666666666668,r=10+1*a,s=80/2;let h=a,u=r;if(e>r){const p=(e-10)/1,f=(90-e)/1;h=Math.min(p,f),u=e}return{xLabel:"Workers L",yLabel:"Wage, value of work",xDomain:[0,80],yDomain:[0,100],series:[{kind:"line",name:"Value of marginal worker (demand)",pts:m(c(p=>90-1*p,0,80),0,100),color:1},{kind:"line",name:"Labour supply (wage needed)",pts:m(c(p=>10+1*p,0,80),0,100),color:2},{kind:"line",name:"Marginal cost of labour",pts:m(c(p=>10+2*p,0,80),0,100),color:2,dash:!0},...e>0?[{kind:"line",name:"Minimum wage",pts:[{x:0,y:e},{x:80,y:e}],color:4,dash:!0}]:[]],annots:[{kind:"dot",x:h,y:u,label:"Outcome"},{kind:"dot",x:s,y:90-1*s,label:"Competitive"}],readouts:[{label:"Employment",value:i(h)},{label:"Wage",value:i(u)},{label:"Monopsony employment (no minimum)",value:i(a)},{label:"Competitive employment",value:i(s)}]}},brief:"A single big employer must raise the wage for everyone to hire one more worker, so it hires fewer workers at a lower wage than a competitive market. A well chosen minimum wage can raise both wages and employment.",read:["The marginal cost of labour lies above supply, because a higher wage applies to all workers.","The monopsonist hires where the value of the marginal worker equals the marginal cost of labour, and pays the supply wage.","A minimum wage between the monopsony wage and the competitive wage raises employment."],example:"Without a minimum: $L = 26.7$ at wage 36.7. Competitive: $L = 40$ at wage 50. A minimum of 45 raises employment to 35.",scenario:"**Case: a tea estate in a remote district.** It may be the only large employer. A minimum wage set near the competitive level can raise both pay and the number of workers hired.",mistakes:["Assuming minimum wages always cost jobs.","Setting the minimum far above the competitive wage, which reduces jobs even here."],tryThis:["Raise the minimum from 0 to 50: watch employment rise then fall.","Find the minimum wage that maximises employment."]},{id:"lorenz",area:"Labour and distribution",title:"Lorenz curve and Gini coefficient",level:"beginner",topic:"poverty-inequality",params:[d("g","Inequality parameter",1,6,.1,2)],build:({g:e})=>({xLabel:"Share of people, poorest first",yLabel:"Share of income",xDomain:[0,1],yDomain:[0,1],series:[{kind:"area",name:"Gap (inequality)",pts:c(t=>t**e,0,1),color:5,opacity:.12,base:0},{kind:"line",name:"Line of equality",pts:[{x:0,y:0},{x:1,y:1}],color:3,dash:!0},{kind:"line",name:"Lorenz curve",pts:c(t=>t**e,0,1),color:1}],annots:[{kind:"dot",x:.5,y:.5**e,label:"Poorest half"}],readouts:[{label:"Gini coefficient",value:i((e-1)/(e+1),3)},{label:"Income share of poorest 50%",value:i(.5**e*100,1)+"%"},{label:"Income share of richest 10%",value:i((1-.9**e)*100,1)+"%"}]}),brief:"The Lorenz curve plots the share of total income held by the poorest x percent. The further it bows below the 45 degree line, the more unequal the distribution. The Gini coefficient is twice the area between them.",read:["Perfect equality is the diagonal: the poorest 50 percent hold 50 percent of income.","Gini runs from 0 (equality) to 1 (one person has everything).","Two different curves can have the same Gini, so look at the whole curve."],example:"With $L(p) = p^2$: the poorest half holds 25 percent of income and $G = \\frac{2-1}{2+1} = 0.33$.",scenario:"**Case: comparing NLSS rounds.** Build the Lorenz curve of consumption per person from two survey rounds. If the new curve lies everywhere above the old, inequality fell unambiguously; if they cross, the answer depends on which part of the distribution you care about.",mistakes:["Reading Gini as the share of income held by someone.","Comparing Ginis computed on income in one survey and consumption in another."],tryThis:["Set the parameter to 1: what is the Gini?","Raise it: how does the share of the richest 10 percent change?"]},{id:"keynesian-cross",area:"Macroeconomics",title:"Keynesian cross and the multiplier",level:"beginner",topic:"is-lm-ad-as",params:[d("G","Government spending",0,60,1,20),d("c","Marginal propensity to consume",.4,.9,.05,.75)],build:({G:e,c:t})=>{const l=(40+e)/(1-t);return{xLabel:"Income Y",yLabel:"Planned spending",xDomain:[0,500],yDomain:[0,500],series:[{kind:"line",name:"45 degree line",pts:[{x:0,y:0},{x:500,y:500}],color:3,dash:!0},{kind:"line",name:"Planned spending C + I + G",pts:m(c(a=>40+e+t*a,0,500),0,500),color:1}],annots:[{kind:"dot",x:l,y:l,label:"Equilibrium"}],readouts:[{label:"Equilibrium income",value:i(l)},{label:"Multiplier 1/(1 - c)",value:i(1/(1-t))},{label:"Effect of 1 more unit of G",value:i(1/(1-t))}]}},brief:"With fixed prices, output adjusts to planned spending. Equilibrium is where planned spending equals income. A rise in spending raises income by a multiple, because spending becomes someone's income and is partly spent again.",read:["The 45 degree line shows points where spending equals income.","The planned spending line has slope c, the marginal propensity to consume.","The multiplier is $1/(1-c)$: larger when people spend more of extra income."],example:"With $c = 0.75$, the multiplier is 4: raising $G$ by 10 raises $Y$ by 40.",scenario:"**Case: government capital spending in Nepal.** In a closed economy the multiplier could be large, but in Nepal much extra spending goes on imports, which leak out. The true multiplier is much smaller: add imports and the slope of spending falls.",mistakes:["Applying this model when prices and interest rates adjust.","Ignoring import leakage in small open economies."],tryThis:["Raise c: how does the multiplier change?","Raise G by 10: does Y rise by 10 times the multiplier?"]},{id:"is-lm",area:"Macroeconomics",title:"IS-LM model",level:"intermediate",topic:"is-lm-ad-as",params:[d("G","Government spending (shifts IS)",0,80,1,40),d("M","Real money supply (shifts LM)",50,250,5,150)],build:({G:e,M:t})=>{const r=150+e,s=f=>(r-(1-.6)*f)/20,h=f=>(.5*f-t)/25,u=(r/20+t/25)/((1-.6)/20+.5/25),p=s(u);return{xLabel:"Output Y",yLabel:"Interest rate r (%)",xDomain:[200,700],yDomain:[0,12],series:[{kind:"line",name:"IS (goods market)",pts:m(c(s,200,700),0,12),color:1},{kind:"line",name:"LM (money market)",pts:m(c(h,200,700),0,12),color:2}],annots:[{kind:"dot",x:u,y:p,label:"Equilibrium"}],readouts:[{label:"Output",value:i(u)},{label:"Interest rate",value:i(p)+"%"}]}},brief:"IS shows combinations of output and interest rate where the goods market clears; LM shows where the money market clears. Their crossing gives short run output and the interest rate.",read:["IS slopes down: lower interest rates raise investment and output.","LM slopes up: higher output raises money demand, so the interest rate must rise for money demand to equal a fixed supply.","Fiscal expansion shifts IS right: output and interest rate rise (some crowding out).","Monetary expansion shifts LM right: output rises and the interest rate falls."],example:"Raising G shifts IS right; output rises by less than the Keynesian cross multiplier because the higher interest rate crowds out investment.",scenario:"**Case: Nepal Rastra Bank easing.** Expanding liquidity shifts LM right. In Nepal, though, the peg to the Indian rupee and open capital links with India limit independent interest rate policy: the textbook model is a starting point, not the whole story.",mistakes:["Forgetting that IS-LM fixes the price level.","Using it for long run questions."],tryThis:["Raise G: how much does r rise?","Raise M with G fixed: what happens to Y?"]},{id:"ad-as",area:"Macroeconomics",title:"Aggregate demand and aggregate supply",level:"intermediate",topic:"is-lm-ad-as",params:[d("d","Demand shock",-30,30,1,0),d("s","Supply shock (cost push)",-20,20,1,0)],build:({d:e,s:t})=>{const a=u=>200+e-u,r=u=>100+t+.8*(u-100),s=(200+e-100-t+80)/1.8,h=a(s);return{xLabel:"Real output Y",yLabel:"Price level P",xDomain:[60,140],yDomain:[60,140],series:[{kind:"line",name:"Aggregate demand",pts:m(c(a,60,140),60,140),color:1},{kind:"line",name:"Short run aggregate supply",pts:m(c(r,60,140),60,140),color:2},{kind:"line",name:"Long run supply (potential)",pts:[{x:100,y:60},{x:100,y:140}],color:3,dash:!0}],annots:[{kind:"dot",x:s,y:h,label:"Short run"}],readouts:[{label:"Output",value:i(s)},{label:"Price level",value:i(h)},{label:"Output gap",value:i(s-100)}]}},brief:"Aggregate demand slopes down; short run supply slopes up; long run supply is vertical at potential output. Demand shocks move output and prices in the same direction; supply shocks move them in opposite directions (stagflation).",read:["A positive demand shock raises output and prices in the short run.","A cost push supply shock (oil prices) raises prices and lowers output.","In the long run, output returns to potential as expectations adjust."],example:"A demand shock of +20 raises output above potential (a positive gap) and pushes up prices.",scenario:"**Case: a fall in remittances.** Lower household income shifts AD left: output and inflation fall. A rise in Indian fuel prices passes through to Nepal as a supply shock: prices rise while output falls.",mistakes:["Treating AD like a market demand curve: it slopes down for different reasons (wealth, interest rate, exchange rate effects).","Forgetting the long run vertical supply."],tryThis:["Apply a supply shock of +15: what happens to output and prices?","Combine a negative demand and positive supply shock: is the price effect clear?"]},{id:"phillips",area:"Macroeconomics",title:"Phillips curve: short run and long run",level:"intermediate",topic:"phillips-curve",params:[d("pe","Expected inflation (%)",0,10,.5,4),d("beta","Slope",.2,2,.1,.8)],build:({pe:e,beta:t})=>({xLabel:"Unemployment rate (%)",yLabel:"Inflation (%)",xDomain:[0,12],yDomain:[-4,16],series:[{kind:"line",name:"Short run Phillips curve",pts:m(c(o=>e-t*(o-5),0,12),-4,16),color:1},{kind:"line",name:"Long run (natural rate)",pts:[{x:5,y:-4},{x:5,y:16}],color:3,dash:!0}],annots:[{kind:"dot",x:5,y:e,label:"Natural rate"}],readouts:[{label:"Inflation at 3% unemployment",value:i(e-t*-2)+"%"},{label:"Inflation at 7% unemployment",value:i(e-t*2)+"%"}]}),brief:"In the short run, lower unemployment comes with higher inflation. In the long run, once expectations adjust, there is no trade-off: unemployment returns to its natural rate at any inflation rate.",read:["The short run curve shifts up when expected inflation rises.","Trying to hold unemployment below the natural rate leads to rising inflation (the accelerationist idea of Friedman and Phelps).","Credible central banks can keep expectations anchored."],example:"With expected inflation 4 percent and slope 0.8, cutting unemployment from 5 to 3 percent raises inflation to 5.6 percent, until expectations rise.",scenario:"**Case: inflation in Nepal.** Much of Nepal's inflation is imported from India through the peg, so domestic slack explains less of it. A Phillips curve for Nepal would include Indian inflation as a key driver.",mistakes:["Treating the short run curve as a permanent menu.","Ignoring supply shocks, which shift the curve."],tryThis:["Raise expected inflation: where does the curve move?","Flatten the slope: what does that mean for the cost of cutting inflation?"]},{id:"laffer",area:"Macroeconomics",title:"Laffer curve",level:"intermediate",params:[d("e","Responsiveness of the tax base",.2,4,.1,1)],build:({e})=>{const t=o=>o*(1-o)**e*100,n=1/(1+e);return{xLabel:"Tax rate",yLabel:"Tax revenue",xDomain:[0,1],yDomain:[0,60],series:[{kind:"line",name:"Revenue",pts:m(c(t,0,1),0,60),color:1}],annots:[{kind:"vline",x:n,label:"Revenue maximising rate"}],readouts:[{label:"Revenue maximising tax rate",value:i(n*100,1)+"%"},{label:"Maximum revenue",value:i(t(n))}]}},brief:"Revenue is zero at a 0 percent and at a 100 percent tax rate, so there is a rate in between that raises the most. Beyond it, cutting rates would raise revenue. Where that point lies depends on how strongly the tax base responds.",read:["The more responsive the base (higher elasticity), the lower the revenue maximising rate.","Being on the left side means tax cuts lose revenue, as is usual in practice.","The revenue maximising rate is not the optimal rate; it ignores the welfare of taxpayers."],example:"With revenue $R = t(1-t)^{e}$, the maximum is at $t^* = 1/(1+e)$: 50 percent when $e = 1$.",scenario:"**Case: customs duties on gold.** Very high duties push trade into smuggling (a responsive base), so lowering the duty might raise recorded revenue. For a broad VAT with low evasion, the base is less responsive.",mistakes:["Assuming any tax cut pays for itself.","Confusing the revenue maximising rate with the best rate."],tryThis:["Raise the responsiveness: where does the peak move?"]},{id:"solow",area:"Growth",title:"Solow model: steady state",level:"intermediate",topic:"solow",params:[d("s","Saving rate",.05,.6,.01,.25),d("nd","Population growth plus depreciation",.02,.15,.005,.07),d("al","Capital share alpha",.2,.6,.01,.33)],build:({s:e,nd:t,al:n})=>{const o=(e/t)**(1/(1-n)),l=o**n,a=Math.max(o*2.2,5),r=Math.max(a**n*1.1,1);return{xLabel:"Capital per worker k",yLabel:"Per worker",xDomain:[0,a],yDomain:[0,r],series:[{kind:"line",name:"Output per worker f(k)",pts:m(c(s=>s**n,0,a),0,r),color:1},{kind:"line",name:"Investment s f(k)",pts:m(c(s=>e*s**n,0,a),0,r),color:3},{kind:"line",name:"Break-even (n + d) k",pts:m(c(s=>t*s,0,a),0,r),color:5}],annots:[{kind:"dot",x:o,y:e*l,label:"k*"},{kind:"segment",x1:o,y1:0,x2:o,y2:l,dash:!0}],readouts:[{label:"Steady state k*",value:i(o,3)},{label:"Output per worker y*",value:i(l,3)},{label:"Consumption per worker",value:i((1-e)*l,3)}]}},brief:"Capital per worker grows when investment exceeds what is needed to equip new workers and replace worn out capital. It settles at a steady state where the two are equal. A higher saving rate raises the level of income, not its long run growth rate.",read:["Where investment (green) is above break-even (red), capital per worker rises.","The steady state is where they cross.","Diminishing returns (the curve flattens) are why growth from capital alone eventually stops.","Long run growth in income per worker needs technological progress."],example:"With $y = k^{1/3}$, $s = 0.25$, $n + \\delta = 0.07$: $k^* = (0.25/0.07)^{1.5} = 6.75$ and $y^* = 1.89$.",scenario:"**Case: Nepal's low investment in machines and infrastructure.** Raising investment raises income per worker toward a higher steady state, but faster population growth or high depreciation (for example from floods damaging roads) lowers it.",mistakes:["Saying higher saving raises the long run growth rate: it raises the level.","Forgetting depreciation and population growth in the break-even line."],tryThis:["Raise the saving rate: what happens to k* and to consumption?","Raise n + d: how does the steady state change?"]},{id:"golden-rule",area:"Growth",title:"Golden rule: maximising consumption",level:"advanced",topic:"solow",params:[d("s","Saving rate",.05,.9,.01,.25),d("al","Capital share alpha",.2,.6,.01,.33)],build:({s:e,al:t})=>{const o=s=>s**t-.07*s,l=(t/.07)**(1/(1-t)),a=(e/.07)**(1/(1-t)),r=Math.max(l,a)*1.5;return{xLabel:"Steady state capital per worker k",yLabel:"Steady state consumption c",xDomain:[0,r],yDomain:[0,Math.max(o(l)*1.3,.1)],series:[{kind:"line",name:"c(k) = f(k) - (n + d)k",pts:m(c(o,0,r),0,100),color:1}],annots:[{kind:"dot",x:l,y:o(l),label:"Golden rule"},{kind:"dot",x:a,y:o(a),label:"Your saving rate"}],readouts:[{label:"Golden rule saving rate",value:i(t*100,1)+"%"},{label:"Steady state consumption now",value:i(o(a),3)},{label:"Golden rule consumption",value:i(o(l),3)},{label:"Verdict",value:e>t?"Saving too much (dynamically inefficient)":e<t?"Saving less than the golden rule":"At the golden rule"}]}},brief:"Among all steady states, the golden rule one gives the highest consumption per worker. It is reached by saving a share of income equal to capital's share alpha.",read:["Steady state consumption first rises and then falls with capital.","At the golden rule, the marginal product of capital equals $n + \\delta$.","Saving more than the golden rule rate lowers consumption forever: dynamic inefficiency."],example:"With $\\alpha = 0.33$, the golden rule saving rate is 33 percent.",scenario:"**Case: high saving economies.** Some fast growing Asian economies have saved very large shares of income; asking whether they are above the golden rule is a classic exam and policy question.",mistakes:["Thinking the golden rule is always the best target: getting there may require sacrificing current consumption.","Confusing the golden rule saving rate with the steady state."],tryThis:["Set saving equal to alpha: the dots meet.","Set saving to 0.8: is consumption higher or lower?"]},{id:"tariff",area:"International",title:"Tariff in a small open economy",level:"intermediate",params:[d("t","Tariff per unit",0,30,1,10)],build:({t:e})=>{const r=30+e,s=20/1,h=70/1,u=Math.max(0,(r-10)/1),p=(100-r)/1,f=Math.max(0,p-u),v=e*f,b=.5*e*(u-s)+.5*e*(h-p);return{xLabel:"Quantity",yLabel:"Price",xDomain:[0,100],yDomain:[0,100],series:[{kind:"polygon",name:"Tariff revenue",pts:[{x:u,y:30},{x:p,y:30},{x:p,y:r},{x:u,y:r}],color:4,opacity:.18},{kind:"polygon",name:"Production loss",pts:[{x:s,y:30},{x:u,y:30},{x:u,y:r}],color:5,opacity:.3},{kind:"polygon",name:"Consumption loss",pts:[{x:p,y:30},{x:h,y:30},{x:p,y:r}],color:5,opacity:.3},{kind:"line",name:"Domestic demand",pts:c(w=>100-1*w,0,100),color:1},{kind:"line",name:"Domestic supply",pts:m(c(w=>10+1*w,0,100),0,100),color:2},{kind:"line",name:"World price",pts:[{x:0,y:30},{x:100,y:30}],color:3,dash:!0},{kind:"line",name:"World price plus tariff",pts:[{x:0,y:r},{x:100,y:r}],color:4,dash:!0}],readouts:[{label:"Imports without tariff",value:i(h-s)},{label:"Imports with tariff",value:i(f)},{label:"Tariff revenue",value:i(v)},{label:"Deadweight loss",value:i(b)}]}},brief:"A small country takes the world price as given. A tariff raises the domestic price by the tariff: domestic producers expand, consumers buy less, imports fall, the government collects revenue, and two triangles of efficiency are lost.",read:["Imports are the gap between domestic demand and supply at the domestic price.","The left red triangle is the cost of producing at home what could be imported more cheaply; the right one is lost consumption.","Producers gain and consumers lose more than the producers and government together gain."],example:"World price 30, tariff 10: imports fall from 50 to 30, revenue 300, deadweight loss 100.",scenario:"**Case: Nepali tariffs on imported vegetables.** A tariff protects Nepali farmers but raises prices for urban consumers. With an open border to India, high tariffs also invite informal trade, so revenue may be lower than the graph suggests.",mistakes:["Counting tariff revenue as a pure loss to the economy: it is a transfer.","Applying the small country model to a country that can affect world prices."],tryThis:["Find the tariff that eliminates imports (prohibitive tariff).","How fast does the deadweight loss grow with the tariff?"]},{id:"forex",area:"International",title:"Foreign exchange market and remittances",level:"intermediate",params:[d("rem","Remittance inflow (shifts dollar supply)",0,40,1,10),d("imp","Import demand (shifts dollar demand)",0,40,1,10)],build:({rem:e,imp:t})=>{const n=r=>200+t*2-1.5*r,o=r=>20-e*2+1.2*r,l=(180+t*2+e*2)/2.7,a=n(l);return{xLabel:"Dollars traded",yLabel:"Rupees per dollar (index)",xDomain:[0,140],yDomain:[0,250],series:[{kind:"line",name:"Demand for dollars (imports)",pts:m(c(n,0,140),0,250),color:1},{kind:"line",name:"Supply of dollars (remittances, exports)",pts:m(c(o,0,140),0,250),color:2}],annots:[{kind:"dot",x:l,y:a,label:"Market rate"}],readouts:[{label:"Market exchange rate (index)",value:i(a)},{label:"Dollars traded",value:i(l)}]}},brief:"Under a floating rate, the price of foreign currency is set by demand (to pay for imports and investments abroad) and supply (from exports, remittances and inflows). More supply of dollars makes the dollar cheaper: the home currency appreciates.",read:["Up on the vertical axis means more rupees per dollar: a weaker rupee.","More remittances shift dollar supply right: the rupee strengthens.","More import demand shifts dollar demand right: the rupee weakens."],example:"Raising remittances from 10 to 20 lowers the index rate: the rupee appreciates.",scenario:"**Case: Nepal's actual regime.** The Nepali rupee is pegged to the Indian rupee, so against the dollar it moves with the Indian rupee. Under the peg, remittance inflows show up mainly as higher foreign exchange reserves at Nepal Rastra Bank rather than a stronger rupee. This graph shows what a float would look like.",mistakes:["Forgetting that a higher rupees per dollar number means a weaker rupee.","Applying a floating rate model to a pegged currency without adjustment."],tryThis:["Raise imports and remittances together: does the rate move?"]},{id:"sampling",area:"Statistics and econometrics",title:"Sampling distribution and confidence intervals",level:"beginner",topic:"lln-clt",params:[d("n","Sample size",5,400,5,25),d("sigma","Population standard deviation",5,40,1,20)],build:({n:e,sigma:t})=>{const o=t/Math.sqrt(e),l=r=>Math.exp(-.5*((r-100)/o)**2)/(o*Math.sqrt(2*Math.PI)),a=l(100)*1.15;return{xLabel:"Sample mean",yLabel:"Density",xDomain:[60,140],yDomain:[0,a],series:[{kind:"area",name:"95% of sample means",pts:c(l,100-1.96*o,100+1.96*o),color:1,opacity:.2,base:0},{kind:"line",name:"Distribution of the sample mean",pts:c(l,60,140,160),color:1}],annots:[{kind:"vline",x:100,label:"True mean"}],readouts:[{label:"Standard error",value:i(o)},{label:"95% interval half width",value:i(1.96*o)}]}},brief:"If you took many samples, their means would form a distribution centred on the true mean. Its spread, the standard error, shrinks with the square root of the sample size. That is why larger samples give more precise estimates.",read:["Quadrupling the sample halves the standard error.","About 95 percent of sample means fall within 1.96 standard errors of the true mean.","By the central limit theorem this shape is approximately normal even if incomes are skewed."],example:"With $\\sigma = 20$ and $n = 25$, $SE = 4$ and the 95 percent margin is 7.84. With $n = 100$ it halves to 3.92.",scenario:"**Case: planning a household survey in a Nepali district.** If spending varies a lot (large sigma), you need many more households to estimate the average precisely. This is the logic behind power calculations for any field study.",mistakes:["Thinking the standard error falls in proportion to n: it falls with the square root.","Confusing the standard deviation of incomes with the standard error of the mean."],tryThis:["Multiply n by 4: what happens to the interval?"]},{id:"ols-line",area:"Statistics and econometrics",title:"Regression line and the effect of noise",level:"beginner",topic:"ols-simple",params:[d("beta","True slope",-2,3,.1,1.5),d("noise","Noise",0,6,.25,2)],build:({beta:e,noise:t})=>{const n=Array.from({length:30},(y,g)=>1+g*9/29),o=y=>Math.sin(y*12.9898)*43758.5453%1,l=n.map((y,g)=>(o(g)+o(g+50)-(o(g+100)+o(g+150)))*t),a=n.map((y,g)=>2+e*y+l[g]),r=n.reduce((y,g)=>y+g,0)/n.length,s=a.reduce((y,g)=>y+g,0)/a.length,h=n.reduce((y,g,x)=>y+(g-r)*(a[x]-s),0),u=n.reduce((y,g)=>y+(g-r)**2,0),p=h/u,f=s-p*r,v=a.reduce((y,g)=>y+(g-s)**2,0),b=a.reduce((y,g,x)=>y+(g-f-p*n[x])**2,0),w=v?1-b/v:1;return{xLabel:"x (for example years of schooling)",yLabel:"y (for example log earnings, scaled)",xDomain:[0,11],yDomain:[Math.min(...a,0)-2,Math.max(...a,10)+2],series:[{kind:"points",name:"Data",pts:n.map((y,g)=>({x:y,y:a[g]})),color:1},{kind:"line",name:"OLS fitted line",pts:[{x:0,y:f},{x:11,y:f+p*11}],color:5},{kind:"line",name:"True line",pts:[{x:0,y:2},{x:11,y:2+e*11}],color:3,dash:!0}],readouts:[{label:"Estimated slope",value:i(p,3)},{label:"True slope",value:i(e)},{label:"R-squared",value:i(w,3)}]}},brief:"OLS draws the line that minimises the sum of squared vertical distances to the data. More noise scatters the points: the estimate is less precise and R-squared falls, but with exogenous noise the estimate is still centred on the truth.",read:["The red line is the estimate; the dashed green line is the truth used to make the data.","Noise lowers R-squared without biasing the slope.","Bias comes from omitted variables or reverse causality, not from noise in y."],example:"With little noise the fitted slope is close to the true one and R-squared is near 1; with heavy noise R-squared falls sharply while the slope stays roughly right.",scenario:"**Case: returns to schooling in Nepal.** Earnings depend on many things besides schooling, so R-squared is low. That does not make the schooling coefficient wrong; what matters is whether schooling is correlated with omitted ability or family background.",mistakes:["Judging a causal estimate by R-squared.","Thinking noise causes bias."],tryThis:["Set noise to 0: what are R-squared and the slope?","Raise noise to 6: how far does the slope move?"]},{id:"did-plot",area:"Statistics and econometrics",title:"Difference-in-differences and parallel trends",level:"intermediate",topic:"did",params:[d("eff","True treatment effect",-10,15,.5,6),d("gap","Pre-trend violation",-3,3,.1,0)],build:({eff:e,gap:t})=>{const n=[0,1,2,3,4,5],o=n.map(s=>20+2*s),l=n.map(s=>26+(2+t)*s+(s>=3?e:0)),a=n.map(s=>26+(2+t)*s),r=l[4]-l[2]-(o[4]-o[2]);return{xLabel:"Year (treatment starts in year 3)",yLabel:"Outcome",xDomain:[0,5],yDomain:[10,60],series:[{kind:"line",name:"Comparison group",pts:n.map((s,h)=>({x:s,y:o[h]})),color:2},{kind:"line",name:"Treated group",pts:n.map((s,h)=>({x:s,y:l[h]})),color:1},{kind:"line",name:"Treated without treatment (counterfactual)",pts:n.slice(2).map((s,h)=>({x:s,y:a[h+2]})),color:1,dash:!0}],annots:[{kind:"vline",x:2.5,label:"Treatment"}],readouts:[{label:"DiD estimate (years 2 to 4)",value:i(r)},{label:"True effect",value:i(e)},{label:"Bias from pre-trend",value:i(r-e)}]}},brief:"Difference-in-differences compares the change in the treated group with the change in a comparison group. It recovers the true effect only if, without treatment, both groups would have followed parallel trends.",read:["Before treatment, the two lines should be parallel.","The dashed line is what the treated group would have done without treatment.","If trends differ before treatment, the estimate is biased by the difference in trends."],example:"With parallel trends the estimate equals the true effect. A pre-trend violation of 1 per year adds a bias of 2 over two years.",scenario:"**Case: a district cash transfer pilot in Nepal.** Compare attendance changes in pilot and non-pilot districts. Plot several years before the pilot: if pilot districts were already improving faster, the simple estimate overstates the effect.",mistakes:["Skipping the pre-trend plot.","Using a comparison group that was affected by the policy too."],tryThis:["Add a pre-trend of 1: how large is the bias?","Set the effect to 0 with a pre-trend: you get a false effect."]},{id:"rd-plot",area:"Statistics and econometrics",title:"Regression discontinuity",level:"intermediate",topic:"rdd",params:[d("jump","Effect at the cutoff",-10,15,.5,6),d("slope","Slope of the outcome in the running variable",-1,1,.05,.4)],build:({jump:e,slope:t})=>{const n=Array.from({length:41},(a,r)=>30+r),o=a=>Math.sin(a*78.233)*43758.5453%1,l=n.map((a,r)=>20+t*(a-50)+(a>=50?e:0)+o(r)*3);return{xLabel:"Running variable (for example exam score; cutoff 50)",yLabel:"Outcome",xDomain:[30,70],yDomain:[0,50],series:[{kind:"points",name:"Data",pts:n.map((a,r)=>({x:a,y:l[r]})),color:1},{kind:"line",name:"Fit below cutoff",pts:[{x:30,y:20+t*-20},{x:50,y:20}],color:2},{kind:"line",name:"Fit above cutoff",pts:[{x:50,y:20+e},{x:70,y:20+e+t*20}],color:5}],annots:[{kind:"vline",x:50,label:"Cutoff"}],readouts:[{label:"Jump at the cutoff (effect)",value:i(e)}]}},brief:"When treatment is given to everyone above a cutoff (a score, an age, a poverty index), people just above and just below are almost identical. The jump in outcomes at the cutoff measures the effect of treatment for people near it.",read:["Fit separate lines on each side and measure the gap at the cutoff.","The design fails if people can manipulate their score to cross the cutoff.","The estimate is local: it applies to people near the cutoff."],example:"A scholarship given to students scoring 50 or more: outcomes jump by about the true effect at 50.",scenario:"**Case: a means tested allowance in Nepal.** If eligibility depends on a poverty score cutoff, comparing households just above and below the cutoff estimates the allowance's effect, provided officials cannot shift scores.",mistakes:["Fitting one line across the cutoff.","Using data far from the cutoff with the wrong functional form."],tryThis:["Set the effect to 0: the lines join.","Make the slope steep: why does the functional form matter more now?"]},{id:"ar1",area:"Statistics and econometrics",title:"Shock persistence: AR(1) impulse response",level:"intermediate",topic:"time-series-arma",params:[d("rho","Persistence rho",0,.99,.01,.7)],build:({rho:e})=>{const t=Array.from({length:21},(o,l)=>({x:l,y:e**l})),n=e>0?Math.log(.5)/Math.log(e):0;return{xLabel:"Periods after the shock",yLabel:"Remaining effect",xDomain:[0,20],yDomain:[0,1.05],series:[{kind:"bars",name:"Effect of a one unit shock",pts:t,color:1}],readouts:[{label:"Half life (periods)",value:e>0?i(n,1):"0"},{label:"Effect after 5 periods",value:i(e**5,3)}]}},brief:"In $y_t = \\rho y_{t-1} + \\varepsilon_t$, a shock fades by the factor rho each period. The closer rho is to 1, the longer shocks last; at 1 they never fade (a unit root).",read:["Each bar is the remaining effect of a shock in period 0.","The half life is how long it takes for half the effect to disappear.","Near 1, the series behaves almost like a random walk: be careful with regressions on such data."],example:"With $\\rho = 0.7$ the half life is about 1.9 periods; with $\\rho = 0.95$ about 13.5.",scenario:"**Case: inflation persistence in Nepal.** If monthly inflation has high persistence, a food price shock affects inflation for many months, and NRB has to watch expectations carefully.",mistakes:["Running OLS on two series with unit roots and trusting the result (spurious regression).",'Reading a negative rho as "no persistence": it means the series overshoots and oscillates around its mean.'],tryThis:["Set rho to 0.99: how long is the half life?","Compare rho = 0.5 and rho = 0.9: how many more periods does the shock last?"]},{id:"risk-aversion",area:"Finance and risk",title:"Risk aversion, certainty equivalent and risk premium",level:"intermediate",params:[d("lo","Bad outcome",10,90,5,20),d("hi","Good outcome",100,300,10,180),d("p","Probability of the good outcome",.1,.9,.05,.5)],build:({lo:e,hi:t,p:n})=>{const o=Math.log,l=n*t+(1-n)*e,a=n*o(t)+(1-n)*o(e),r=Math.exp(a);return{xLabel:"Wealth",yLabel:"Utility ln(w)",xDomain:[0,320],yDomain:[1,6.2],series:[{kind:"line",name:"Utility u(w) = ln w",pts:m(c(s=>o(s),2,320),1,6.2),color:1},{kind:"line",name:"Chord between outcomes",pts:[{x:e,y:o(e)},{x:t,y:o(t)}],color:2,dash:!0}],annots:[{kind:"dot",x:l,y:a,label:"Gamble"},{kind:"dot",x:r,y:a,label:"Certainty equivalent"}],readouts:[{label:"Expected value",value:i(l)},{label:"Certainty equivalent",value:i(r)},{label:"Risk premium",value:i(l-r)}]}},brief:"With concave utility, a gamble is worth less than its expected value. The certainty equivalent is the sure amount giving the same utility; the gap is the risk premium people would pay to avoid risk.",read:["The chord shows expected utility of the gamble; it lies below the curve because utility is concave (Jensen's inequality).","The certainty equivalent is read horizontally from expected utility to the curve.","Greater curvature means more risk aversion and a larger premium."],example:"Outcomes 20 and 180 with equal probability: expected value 100, certainty equivalent $\\sqrt{20 \\times 180} = 60$, risk premium 40.",scenario:"**Case: a farmer choosing between a safe crop and a risky cash crop.** Even if the cash crop pays more on average, a poor, risk averse farmer may prefer the safe crop. Crop insurance shrinks the risk and can unlock the higher return.",mistakes:["Assuming people maximise expected value.","Reading the certainty equivalent vertically instead of horizontally."],tryThis:["Widen the gap between outcomes: what happens to the premium?"]},{id:"yield-curve",area:"Finance and risk",title:"Yield curve shapes",level:"intermediate",params:[d("level","Long run level (%)",2,12,.25,7),d("slope","Short minus long (%)",-4,4,.25,-2)],build:({level:e,slope:t})=>{const n=o=>e+t*((1-Math.exp(-o/2))/(o/2));return{xLabel:"Maturity (years)",yLabel:"Yield (%)",xDomain:[.25,30],yDomain:[0,16],series:[{kind:"line",name:"Yield curve",pts:m(c(n,.25,30),0,16),color:1}],readouts:[{label:"3 month yield",value:i(n(.25))+"%"},{label:"10 year yield",value:i(n(10))+"%"},{label:"Shape",value:n(.25)>n(10)?"Inverted":"Upward sloping"}]}},brief:"The yield curve plots interest rates on bonds of different maturities. Normally it slopes up (long loans pay a term premium). An inverted curve (short rates above long) has often preceded recessions.",read:["Short rates follow the central bank's policy rate.","Long rates reflect expected future short rates and a term premium.","Inversion means markets expect rates to fall, often because they expect a slowdown."],example:"With level 7 and slope -2, short yields are near 5 percent and long yields approach 7 percent: upward sloping.",scenario:"**Case: Nepal's treasury bills and development bonds.** Plotting their yields over time shows how liquidity conditions in the banking system move short rates more than long ones.",mistakes:["Treating inversion as a guaranteed recession signal.","Forgetting the term premium: a flat curve can still mean markets expect rates to fall slightly."],tryThis:["Make slope positive: the curve inverts.","Raise the long run level with the slope fixed: the whole curve shifts up, as when expected inflation rises."]}],$=Object.fromEntries(k.map(e=>[e.id,e])),A=e=>Object.fromEntries(e.params.map(t=>[t.id,t.value]));export{k as G,$ as a,C as b,A as d};
